import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'/.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse((await import('node:fs/promises')).readFile?await (await import('node:fs/promises')).readFile(join(runtime,'linux.json'),'utf8'): '{}');
const browser=await chromium.launch({...config.browser.launchOptions,timeout:30000});
const page=await browser.newPage({viewport:{width:1280,height:900}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3002',{waitUntil:'load'});
await page.waitForTimeout(3000);
await page.locator('[data-action="credits"]').click();
await page.locator('#archive-screen.visible').waitFor();
console.log('archive',await page.locator('#archive-screen h2').innerText(),await page.locator('#archive-screen .archive-entry').count());
await page.locator('#archive-screen [data-lang="en"]').click().catch(()=>{});
await page.locator('#archive-screen [data-action="back"]').click();
await page.locator('[data-action="intro"]').click();
await page.locator('#skip-intro').click();
await page.waitForTimeout(500);
await page.keyboard.press('e');
await page.waitForTimeout(150);
console.log('after journal',await page.locator('#objective-text').innerText(),'objective entries',await page.locator('#log-list li').count());
async function hold(key,ms){await page.keyboard.down(key);await page.waitForTimeout(ms);await page.keyboard.up(key);await page.waitForTimeout(100);}
await hold('w',1650);
await page.keyboard.press('e'); await page.waitForTimeout(200);
console.log('initial gate interaction',await page.locator('#toast').innerText(),await page.locator('#objective-text').innerText());
await hold('w',2800); await hold('a',1200); await hold('w',1400);
await page.keyboard.press('e'); await page.waitForTimeout(200);
console.log('card pickup',await page.locator('#toast').innerText(),await page.locator('#objective-progress').innerText(),await page.locator('#objective-text').innerText());
console.log('errors',errors);
// Return to menu and leave the requested latest visual evidence as a compact JPEG.
await page.keyboard.press('Escape'); await page.waitForTimeout(150); await page.locator('[data-action="quit"]').click();
await page.waitForTimeout(300);
await page.locator('[data-action="credits"]').click(); await page.waitForTimeout(500);
await page.screenshot({path:'screenshots/final-archive.jpg',type:'jpeg',quality:88});
console.log('screenshot',await page.evaluate(()=>({width:document.documentElement.clientWidth,height:document.documentElement.clientHeight,archiveVisible:document.querySelector('#archive-screen').classList.contains('visible')})));
await browser.close();
