cat > /tmp/facility-check.cjs <<'EOF'
const { createRequire } = require('node:module')
const { readFileSync, mkdirSync } = require('node:fs')
const { join } = require('node:path')
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))

;(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  await page.route('**/src/game.js', async route => {
    const response = await route.fetch()
    const source = await response.text()
    await route.fulfill({ response, body: `${source}\nwindow.__facilityTest={game,player,interactables,nearInteraction,resetRun};` })
  })
  await page.goto('http://127.0.0.1:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => document.querySelector('#main-menu h1') && document.querySelector('#game')?.width > 0)
  await page.locator('[data-action="credits"]').click()
  await page.waitForFunction(() => document.querySelector('#archive-screen')?.classList.contains('visible'))
  const archiveText = await page.locator('#archive-screen').innerText()
  if (!archiveText.includes('KING LOOK.S') || !archiveText.includes('THREE.JS')) throw new Error('Archive content missing')
  mkdirSync('screenshots', { recursive: true })
  await page.screenshot({ path: 'screenshots/final-archive.jpg', type: 'jpeg', quality: 85 })
  console.log('Archive navigation/content verified; saved 1280x800 JPEG.')
  await page.locator('#archive-screen [data-action="back"]').click()
  await page.locator('[data-action="intro"]').click()
  await page.locator('#skip-intro').click()
  await page.waitForFunction(() => document.querySelector('#game-ui')?.classList.contains('active'))
  const progression = await page.evaluate(() => {
    const t = window.__facilityTest
    const assert = (ok, message) => { if (!ok) throw new Error(message) }
    const interaction = (kind, x, z) => t.interactables.find(it => it.kind === kind && Math.abs(it.pos.x-x)<.01 && Math.abs(it.pos.z-z)<.1)
    t.resetRun()
    const lab = interaction('key', 4, -42)
    assert(lab && lab.fn() === false && !lab.used && t.game.keys === 0, 'Out-of-order LAB card should remain available')
    const med = interaction('key', -4, -19)
    assert(med && med.fn() !== false && t.game.keys === 1 && !med.used, 'MED keycard should collect in sequence')
    const medGate = interaction('door', 0, -25.5)
    medGate.fn()
    assert(t.game.phase >= 2 && !t.game.doors.medDoor.visible, 'MED gate should unlock and advance phase')
    lab.fn()
    assert(t.game.keys === 2, 'LAB keycard should collect after MED')
    interaction('door', 0, -49.3).fn()
    const reactor = interaction('key', -3, -55)
    reactor.fn()
    assert(t.game.keys === 3, 'REACTOR keycard should collect third')
    interaction('generator', 4, -62).fn()
    assert(t.game.power && t.game.phase === 4, 'Generator should restore main power')
    interaction('door', 0, -70.9).fn()
    assert(!t.game.doors.liftDoor.visible && t.game.phase >= 6, 'Powered lift gate should open and advance phase')
    const lift = interaction('lift', 3.35, -82)
    lift.fn()
    assert(t.game.called && t.game.phase === 5, 'Lift call should begin survival sequence')
    t.game.hold = 0
    lift.fn()
    assert(t.game.ending, 'Lift panel should complete the successful ending after the timer')
    return { keys: t.game.keys, phase: t.game.phase, power: t.game.power, ending: t.game.ending }
  })
  console.log('Progression verified:', JSON.stringify(progression))
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`)
  await browser.close()
})().catch(error => { console.error(error); process.exit(1) })
EOF
